    payload=bytes(MainCodeFile(current,BASE).sections[3].data[:-48]);require(len(payload)==123264,'exact deployed item payload')
    def fields(row):
        p=row['pointer_field']
        if row.get('source_null'):
            require(row['current_null'] and source[p:p+4]==current[p:p+4]==bytes(4),'exact null middle preserved');return
        require(int.from_bytes(source[p:p+4],'little')==row['source_pointer'] and int.from_bytes(current[p:p+4],'little')==row['current_pointer'],'exact name/item pointers')
        for arm,which in [(source,'source'),(current,'current')]:
            at=row[which+'_storage_offset'];raw=bytes.fromhex(row[which+'_terminated_hex']);require(raw[-1]==0 and 0 not in raw[:-1],'independent name/item terminator')
