    item=load(doc['source_named_item_binding']);require(all(item[k] for k in ['Samwell_mixed_Japanese_full_catalogue_wording_not_editorially_approved','candidate_spelling_not_shipped_or_globally_approved','source_named_shield_not_runtime_FI_substitution','current_Giant_Tortoise_Shield_asset_andreported_iron_hard_shell_source_meaning_bound','no_item_or_actor_asset_change_or_duplicate_credit','no_inventory_card_orcomplete_item_mechanic_approval','full207_name_role_alias_andSamwell_middle_consumer_review_remains_open']),'item/name binding scope')
    r=item['source_named_item'];require((r['record_ID'],r['Japanese'],r['English'],r['source_terminated_hex'],r['current_terminated_hex'])==('DK4_ITEM_POINTER_053','巨大ゾウガメの盾','Giant Tortoise Shield','8b9091e5835d8345834b838182cc8f8200','4769616e7420546f72746f69736520536869656c6400'),'exact named shield');fields(r)
    require((r['pointer_field'],r['source_storage_offset'],r['current_storage_kind'],r['current_storage_offset'])==(1173256,1435752,'verified-current-staged-payload',132),'item53 storage class andrelative offset;not static ARM9 offset')
    np=load(doc['native_name_proof']);require(np['name_literal_alignment_count']==np['exact_reused_native_name_font_alignment_cases']==32 and np['fresh_native_name_font_alignment_cases']==0 and np['complete_name_component_plane_count']==8 and np['Samwell_mixed_Japanese_catalogue_plane_is_technical_evidence_not_wording_approval'],'exact reused name-font scope')
    callback=load(doc['callback_completed_review']);previous={r['source_record_index']:r for r in callback['records']};newrows={r['source_record_index']:r for r in doc['records']}
    require(sha(Path(doc['callback_completed_review']).read_bytes())==doc['callback_completed_review_sha256'] and previous[28]['english'].split('}',1)[1].endswith(newrows[34]['english'].split('}',1)[1]) and previous[46]['english'].split('}',1)[1]==newrows[59]['english'].split('}',1)[1],'exact source-supported B228 pitch andreassurance callbacks')
    entry=load(doc['source_entry_proof']);require(sha(Path(doc['source_entry_proof']).read_bytes())==doc['source_entry_proof_sha256'] and entry['original_source_EV2_and_action_table_exact'] and [(r['event_ID'],r['script_block'],r['action_index'],r['must_be_completed'],r['must_not_be_completed']) for r in entry['selected_B229_source_events']]==[(229,229,230,[228],[])],'original229 requires228;not forced eligibility')
    middle=item['Samwell_middle_field'];require(middle==next(n for n in names['records'] if n['actor_ID']==22)['source_fields'][2] and middle['Japanese']==middle['current_English']=='ダ' and middle['source_terminated_hex']==middle['current_terminated_hex']=='835f00','unapproved source middle retained exactly')
    a,l=load(doc['actual_English_proof']),load(doc['later_scope_proof']);o=mapping['observed_comparison_contract']
    measured=dict(source_exit=a['source_exit_frame'],English_exit=a['exit_frame'],normal_port=a['normal_port_sample_frame'],body_holds=a['actual_complete_body_holds'],name_holds=a['actual_complete_name_holds'],command_difference_rows=len(a['command_comparison_differences']),duration_changes=len(a['command_duration_changes']),later_samples=len(a['later_sampled_whole_frame_comparisons']),later_RGB_differences=len(l['later_sampled_RGB_differences']),component_equality=l['five_native_component_equality'],captains=l['captain_IDs'],PRNG_seeds=l['final_PRNG_seeds'],following_B120_ends=[r['B120_end_frames'] for r in l['following_B120']])
    require(measured==o==seal['observed_comparison_contract'],'all actual measured comparisons preserved')
    require(o==dict(source_exit=6935,English_exit=6933,normal_port=7030,body_holds=67,name_holds=67,command_difference_rows=10,duration_changes=3,later_samples=151,later_RGB_differences=88,component_equality=dict(state=True,models=False,persistent_objects=False,tasks=True,calendar=False),captains=[2,2],PRNG_seeds=[2748498268,2743647194],following_B120_ends=[[11736],[11736]]),'approved measured comparison')
    require(a['actual_native_pages']==len(a['actual_page_panels'])==17 and not a['incomplete_sampled_body_holds'] and len(a['semantic_upper_portrait_pairs'])==17 and not a['page_transitions'] and all(a[k] for k in ['all17_single_original_native_pages_verified','initialized_B22_not_natural_event229_original_location_earned_progress_full_effects_route_orhardware','no_roles_roster_funds_conditions_RNG_results_RAM_code_battery_or_savestate_forced','no_full_RAM_every_intermediate_frame_future_sequence_broad_simulation_orcausal_claim','full207_name_role_alias_andearlier_editorial_scope_open','both_source_personal_names_preserved','all_following_resident_payloads_verified_against_actual_SC0_to_SC3_bank','Samwell_mixed_Japanese_full_catalogue_middle_unapproved','progressive_header_approval_only_no_name_asset_change']),'actual pages andcoverage limits')
    plan=load(next(p for p in a['evidence'] if Path(p).name=='run_plan.json'));fixture=load(a['fixture']);require(plan['source_event229_not_naturally_selected'] and plan['displayed_original_source_block']==229 and fixture['fixtures'][0]['source_block']==229 and fixture['initialized_Amsterdam_B22_not_natural_event229_location_or_earned_progress'],'actual B229 entry scope')
    for p in a['actual_page_panels']:require(p['complete_body_holds'] and all(h['complete_independent_native_body_black_gray_all_glyphs_equal'] for h in p['complete_body_holds']),'every actual page complete')
    for p in a['actual_panels']:require(p['native_pages']==1 and {h['native_page'] for h in p['complete_body_holds']}=={1} and {h['native_page'] for h in p['complete_name_holds']}=={1},'every body andname page held')
    c=load(doc['relocated_control_proof']);require(all(c[k] for k in ['all17_complete_preambles_voices_andzero_macro_bodies_bound','zero_original_orinvented_FI_FA_FO','normal_state0_retains_existing_value_word_in_all25_cases','original_normal_end916_four_bytes_andtarget_no_tail_preserved','all19_commands_no_predicate_relative_typed_style_orpicture_assumptions','opaque_A000_effects_bridged_not_fully_explained']),'control boundary scope')
    require(c['source_A000']['source_command_hex']=='00a0ffff35000110' and c['source_A000']['rows']==c['relocated_A000']['rows'] and c['source_A000']['opaque_effect_bridges']==c['relocated_A000']['opaque_effect_bridges'],'effect structural consumer')
